from html import escape
import os
from pathlib import Path

ROOT = Path(__file__).resolve().parents[4]
OUT = Path(__file__).resolve().parent.parent
NAMES = ('接手以来项目推进全景报告.html', '2.0.0技术发布报告.html', '2.0.0用户使用说明书.html')


def e(value):
    return escape(str(value), quote=True)


def link(label, path):
    target = str(path) if str(path).startswith(('https:', '#')) else os.path.relpath(ROOT/path, OUT)
    return f'<a href="{e(target)}">{e(label)}</a>'


def table(headings, rows):
    return '<div class="table-wrap" tabindex="0" role="region" aria-label="可横向滚动的数据表"><table><thead><tr>'+''.join('<th scope="col">'+e(h)+'</th>' for h in headings)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'


def section(ident, title, body, kicker=''):
    return f'<section id="{ident}" class="chapter">'+(f'<p class="eyebrow">{e(kicker)}</p>' if kicker else '')+f'<h2>{e(title)}</h2>{body}</section>'


def cards(items):
    return '<div class="cards">'+''.join(f'<article class="card"><h3>{e(title)}</h3><p>{body}</p></article>' for title, body in items)+'</div>'


def code(text):
    return '<pre><code>'+e(text)+'</code></pre>'


