JS = '''
document.querySelectorAll('[data-filter]').forEach(input=>{
 const scope=input.dataset.filter;const rows=[...document.querySelectorAll('[data-search-scope="'+scope+'"]')];
 const counter=document.querySelector('[data-count="'+scope+'"]');
 input.addEventListener('input',()=>{const q=input.value.toLocaleLowerCase().trim();let n=0;rows.forEach(row=>{const show=!q||row.textContent.toLocaleLowerCase().includes(q);row.hidden=!show;if(show)n++});if(counter)counter.textContent=n+' / '+rows.length+' 项'});
});
document.querySelectorAll('[data-print]').forEach(b=>b.addEventListener('click',()=>window.print()));
'''


def document(kind, title, eyebrow, intro, toc, body, hero_extra='', metrics=()):
    current = ('history', 'technical', 'manual').index(kind)
    nav = '<nav class="report-nav" aria-label="三份报告">'+''.join(f'<a href="{name}"'+(' aria-current="page"' if i == current else '')+'>'+label+'</a>' for i, (name, label) in enumerate(zip(NAMES, ('推进全景', '技术发布', '使用说明'))))+'</nav>'
    sidebar = '<aside class="toc"><p class="eyebrow">阅读导航</p><nav aria-label="目录"><ol>'+''.join(f'<li><a href="#{ident}">{e(label)}</a></li>' for ident, label in toc)+'</ol></nav><button class="print" data-print>打印 / 保存为 PDF</button></aside>'
    meter = '<div class="metrics">'+''.join('<div class="metric"><strong>'+e(value)+'</strong><span>'+e(label)+'</span></div>' for value, label in metrics)+'</div>' if metrics else ''
    hero = f'<header class="hero"><p class="eyebrow">{e(eyebrow)}</p><h1>{title}</h1><div class="lede">{intro}</div>{hero_extra}{meter}</header>'
    if kind == 'manual':
        hero = f'<header class="hero"><div class="hero-grid"><div><p class="eyebrow">{e(eyebrow)}</p><h1>{title}</h1><div class="lede">{intro}</div>{meter}</div>{hero_extra}</div></header>'
    return f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="{'dark' if kind=='technical' else 'light'}"><title>{e(title.replace('<br>', ' '))}</title><style>{BASE_CSS}{THEMES[kind]}</style></head><body class="{kind}"><a class="skip" href="#content">跳转至正文</a><div class="top"><strong>HHU AI AVATAR / REPORTS</strong>{nav}</div><div class="layout">{sidebar}<main id="content" class="main">{hero}{body}<footer class="footer">编制：2026-11-21 · Asia/Shanghai · 文档作者 spinner-bot<br>历史统计截止 ef6053bf；版本批准对象 v2.0.0。本文档新增提交不回写既有发布输入、实验原件或旧封存。<br>{link('报告编制记录','docs/项目报告/2026-11-21/工作记录/计划与进展.md')} · {link('发布批准与暂停记录','audit/2026-11-21-release-2.0.0/发布交付与暂停记录.md')}</footer></main></div><script>{JS}</script></body></html>'''
